INSERT INTO `wpkr_options` (`option_id`,`option_name`,`option_value`,`autoload`) VALUES ('199','_transient_softaculous_pro_templates','a:4:{s:4:\"list\";a:696:{s:7:\"financy\";a:7:{s:4:\"thid\";s:3:\"517\";s:4:\"slug\";s:7:\"financy\";s:4:\"name\";s:7:\"Financy\";s:8:\"category\";s:10:\"consulting\";s:11:\"description\";s:218:\"Financy &ndash; Consulting and Finance Template. Financy is a clean and modern Business design. You can use it for any kind of website like consultancy, Adviser, business, Consultant, Corporate, Finance, Financial etc.\";s:4:\"type\";s:1:\"1\";s:2:\"ai\";s:1:\"1\";}s:7:\"helpers\";a:6:{s:4:\"thid\";s:3:\"512\";s:4:\"slug\";s:7:\"helpers\";s:4:\"name\";s:7:\"Helpers\";s:8:\"category\";s:5:\"event\";s:11:\"description\";s:201:\"Helpers is a clean, highly flexible and beautifully designed theme with fresh and mobile-friendly layouts. Helpers Theme is created for non-profit websites, NGO, Donation and fundraising websites, etc.\";s:4:\"type\";s:1:\"1\";}s:6:\"farmiq\";a:7:{s:4:\"thid\";s:3:\"890\";s:4:\"slug\";s:6:\"farmiq\";s:4:\"name\";s:6:\"Farmiq\";s:8:\"category\";s:6:\"nature\";s:11:\"description\";s:437:\"Farmiq is a modern agriculture and farming theme for organic farms, agribusiness companies, dairy farms, crop cultivation, greenhouse farming, and sustainable agriculture services. It helps businesses showcase farming solutions, fresh produce, agricultural services, and eco-friendly practices with a professional online presence. Perfect for farmers, agriculture startups, food production companies, and rural development organizations.\";s:4:\"type\";s:1:\"2\";s:2:\"ai\";s:1:\"1\";}s:5:\"hexon\";a:7:{s:4:\"thid\";s:3:\"889\";s:4:\"slug\";s:5:\"hexon\";s:4:\"name\";s:5:\"Hexon\";s:8:\"category\";s:10:\"technology\";s:11:\"description\";s:317:\"Hexon is a modern, high-performance cyber security and IT protection solution designed for security agencies, tech startups, data protection services, and digital defense companies. Built with a clean, futuristic design and smooth user experience, Hexon helps you showcase your services with confidence and authority.\";s:4:\"type\";s:1:\"2\";s:2:\"ai\";s:1:\"1\";}s:8:\"explorer\";a:7:{s:4:\"thid\";s:3:\"502\";s:4:\"slug\";s:8:\"explorer\";s:4:\"name\";s:8:\"Explorer\";s:8:\"category\";s:6:\"travel\";s:11:\"description\";s:325:\"Hit the road with Explorer, your new travel companion! Start a captivating new adventure or tourism blog with ease &ndash; you get all the elements a travel blog can ever need, including destination layouts and a fine selection of blog page templates. Start your travel blog with Explorer, the perfect place for your stories.\";s:4:\"type\";s:1:\"1\";s:2:\"ai\";s:1:\"1\";}s:5:\"rugby\";a:6:{s:4:\"thid\";s:3:\"496\";s:4:\"slug\";s:5:\"rugby\";s:4:\"name\";s:5:\"Rugby\";s:8:\"category\";s:6:\"sports\";s:11:\"description\";s:175:\"Rugby is a sports theme exclusively built for football, american football, basketball, baseball, rugby, volleyball, handball etc. It is fully responsive and easy to customize.\";s:4:\"type\";s:1:\"1\";}s:7:\"ecohost\";a:7:{s:4:\"thid\";s:3:\"493\";s:4:\"slug\";s:7:\"ecohost\";s:4:\"name\";s:7:\"Ecohost\";s:8:\"category\";s:7:\"hosting\";s:11:\"description\";s:204:\"Ecohost is a hosting theme is created for hosting provider website or domain registration website. Ecohost is a creative theme is easily customizable and can be use to create any kind of business website.\";s:4:\"type\";s:1:\"1\";s:2:\"ai\";s:1:\"1\";}s:10:\"earthasana\";a:7:{s:4:\"thid\";s:3:\"888\";s:4:\"slug\";s:10:\"earthasana\";s:4:\"name\";s:10:\"Earthasana\";s:8:\"category\";s:6:\"health\";s:11:\"description\";s:162:\"Earthasana is a serene and grounding yoga theme designed for studios, instructors, and wellness brands that embrace the harmony between body, mind, and the earth.\";s:4:\"type\";s:1:\"2\";s:2:\"ai\";s:1:\"1\";}s:10:\"conceptial\";a:7:{s:4:\"thid\";s:3:\"492\";s:4:\"slug\";s:10:\"conceptial\";s:4:\"name\";s:10:\"Conceptial\";s:8:\"category\";s:8:\"business\";s:11:\"description\";s:229:\"Conceptial is a theme used for creating any type of business website for startup, digital agency and corporate business. Conceptial theme has so many customizable features which create any type of creative and responsive website.\";s:4:\"type\";s:1:\"1\";s:2:\"ai\";s:1:\"1\";}s:7:\"softino\";a:6:{s:4:\"thid\";s:3:\"483\";s:4:\"slug\";s:7:\"softino\";s:4:\"name\";s:7:\"Softino\";s:8:\"category\";s:8:\"software\";s:11:\"description\";s:135:\"Softino Theme is a responsive theme created especially for startup, software as service and other technology related business websites.\";s:4:\"type\";s:1:\"1\";}s:9:\"urbankeys\";a:7:{s:4:\"thid\";s:3:\"887\";s:4:\"slug\";s:9:\"urbankeys\";s:4:\"name\";s:9:\"UrbanKeys\";s:8:\"category\";s:10:\"realestate\";s:11:\"description\";s:249:\"UrbanKeys is a modern and powerful Real Estate &amp; Construction theme designed to unlock new opportunities in property development and home ownership. Built for real estate agencies, property developers, construction firms, and independent agents.\";s:4:\"type\";s:1:\"2\";s:2:\"ai\";s:1:\"1\";}s:7:\"academy\";a:6:{s:4:\"thid\";s:3:\"476\";s:4:\"slug\";s:7:\"academy\";s:4:\"name\";s:7:\"Academy\";s:8:\"category\";s:9:\"education\";s:11:\"description\";s:193:\"Academy is a education theme is created for school, college and online tutions website. Academy is a creative theme is easily customizable and can be use to create any kind of business website.\";s:4:\"type\";s:1:\"1\";}s:9:\"immersion\";a:7:{s:4:\"thid\";s:3:\"475\";s:4:\"slug\";s:9:\"immersion\";s:4:\"name\";s:9:\"Immersion\";s:8:\"category\";s:4:\"blog\";s:11:\"description\";s:156:\"Immersion is an awesome, unique, clean and modern theme especially designed for any kind of blog specially personal, photography, travel or biography blogs.\";s:4:\"type\";s:1:\"1\";s:2:\"ai\";s:1:\"1\";}s:4:\"host\";a:6:{s:4:\"thid\";s:3:\"472\";s:4:\"slug\";s:4:\"host\";s:4:\"name\";s:4:\"Host\";s:8:\"category\